import pandas as pd
pd.set_option('display.width',300)
w=pd.read_csv('Analysis/Multimodal_Program_Projection/results/program_context_wide.tsv',sep='\t')
w['cell_type']=w.program_id.str.split('::').str[0]; w['module']=w.program_id.str.split('::').str[1].astype(int)
reg=pd.read_csv('figures/main/fig4_singlecell_programs/source_tables/source_diagnosis_correction_20261014/program_registry_v2.tsv',sep='\t')
pe=pd.read_csv('figures/main/fig4_singlecell_programs/source_tables/source_diagnosis_correction_20261014/primary_effects.tsv',sep='\t')
print('primary rows',len(pe),'q<0.05 in 117:',(pe.qvalue<0.05).sum(), pe.loc[pe.qvalue<0.05,['cell_type','module','beta','qvalue','hc3_qvalue','n_donors']].to_string())
m=w.merge(pe[['cell_type','module','beta','qvalue','hc3_qvalue','n_donors']],on=['cell_type','module'],how='left').merge(reg[['cell_type','module','module_name']],on=['cell_type','module'],how='left')
# Fig 5E display rule
sel=pd.read_csv('Analysis/Multimodal_Program_Projection/results/proteomics/module_protein_histology_burden_masld.tsv',sep='\t')
sp=pd.read_csv('Analysis/Multimodal_Program_Projection/results/spatial/spatial_program_results.tsv',sep='\t')
hb=sel.groupby('program_id').apply(lambda d:(d.robust==True).any()).rename('hist_robust')
ss=sp.groupby('program_id').apply(lambda d:((d.testable==True)&(d.robust==True)).all()).rename('spatial_shared')
m=m.merge(hb,left_on='program_id',right_index=True,how='left').merge(ss,left_on='program_id',right_index=True,how='left')
m['displayed']=(m.gwas_atac_enzyme_genes.fillna(0)>0)|m.hist_robust.fillna(False)|m.spatial_shared.fillna(False)
m[["program_id","program_name","fig3_beta","fig3_q","beta","qvalue","hc3_qvalue","n_donors","gwas_atac_enzyme_genes","hist_robust","spatial_shared","displayed"]].to_csv("/gpfs/commons/groups/sanjana_lab/Cas13/masld_atlas/Analysis/Hypotheses/RESOURCE-REVIEW-20261015T020503Z/scratch/verify-R01-03-coverage/fig5e_22_universe_vs_corrected_fit.tsv",sep="\t",index=False)
print(m[['program_id','program_name','module_name','fig3_beta','fig3_q','beta','qvalue','hc3_qvalue','n_donors','gwas_atac_enzyme_genes','hist_robust','spatial_shared','displayed']].to_string())
print('displayed',m.displayed.sum(),' corrected q<0.05 among 22:',(m.qvalue<0.05).sum(),' among displayed:',((m.qvalue<0.05)&m.displayed).sum())
print('corrected q<0.10 among displayed:',((m.qvalue<0.10)&m.displayed).sum())
print('sign agreement displayed:',(((m.beta>0)==(m.fig3_beta>0))&m.displayed).sum())
